Your expense tracker is below: add what you spend, pick a month, and see the total and a split by category. Amounts show in rupees, and it may forget your entries when you close this chat, so note down anything important.

```page
<!doctype html>
<html><head><meta charset="utf-8">
<style>
body{font-family:system-ui,sans-serif;margin:0;padding:12px;background:#fafaf7;color:#222}
h2{margin:0 0 8px;font-size:18px}
.row{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:8px}
input,select,button{padding:7px;border:1px solid #ccc;border-radius:6px;font-size:14px}
button{background:#2f7d5b;color:#fff;border:0;cursor:pointer}
button.x{background:#c0392b;padding:3px 8px}
.card{background:#fff;border:1px solid #e3e3dc;border-radius:10px;padding:10px;margin-bottom:10px}
.big{font-size:24px;font-weight:600}
.bar{height:8px;background:#2f7d5b;border-radius:4px}
.cat{display:flex;justify-content:space-between;font-size:13px;margin-top:6px}
.item{display:flex;justify-content:space-between;align-items:center;border-top:1px solid #eee;padding:6px 0;font-size:14px}
.sub{color:#777;font-size:12px}
.over{color:#c0392b}
</style></head><body>
<h2>Monthly expenses</h2>
<div class="card">
  <div class="row">
    <input type="month" id="m">
    <input type="number" id="bud" placeholder="Budget (₹)" style="width:120px">
  </div>
  <div class="big" id="tot">₹0</div>
  <div class="sub" id="left"></div>
</div>
<div class="card">
  <div class="row">
    <input type="date" id="d">
    <select id="c">
      <option>Food</option><option>Rent</option><option>Travel</option><option>Bills</option>
      <option>Shopping</option><option>Health</option><option>Fun</option><option>Other</option>
    </select>
    <input type="number" id="a" placeholder="Amount (₹)" style="width:110px">
    <input type="text" id="n" placeholder="Note" style="flex:1;min-width:80px">
    <button type="button" id="add">Add</button>
  </div>
</div>
<div class="card"><div id="cats"></div></div>
<div class="card"><div id="list"></div></div>
<script>
var items=[];
try{items=JSON.parse(localStorage.getItem("exp")||"[]")}catch(e){}
var $=function(i){return document.getElementById(i)};
var today=new Date().toISOString().slice(0,10);
$("d").value=today;$("m").value=today.slice(0,7);
try{$("bud").value=localStorage.getItem("bud")||""}catch(e){}
function inr(n){return "₹"+Number(n).toLocaleString("en-IN")}
function save(){try{localStorage.setItem("exp",JSON.stringify(items));localStorage.setItem("bud",$("bud").value)}catch(e){}}
function render(){
  var m=$("m").value;
  var cur=items.filter(function(x){return x.d.slice(0,7)===m});
  var tot=cur.reduce(function(s,x){return s+x.a},0);
  $("tot").textContent=inr(tot);
  var b=Number($("bud").value);
  $("left").innerHTML=b?(tot>b?'<span class="over">Over budget by '+inr(tot-b)+'</span>':inr(b-tot)+' left of '+inr(b)):"Set a budget to see what is left";
  var by={};cur.forEach(function(x){by[x.c]=(by[x.c]||0)+x.a});
  var cats=$("cats");cats.innerHTML="";
  Object.keys(by).sort(function(p,q){return by[q]-by[p]}).forEach(function(k){
    var w=document.createElement("div");
    w.innerHTML='<div class="cat"><span>'+k+'</span><span>'+inr(by[k])+'</span></div><div class="bar" style="width:'+Math.round(by[k]/tot*100)+'%"></div>';
    cats.appendChild(w);
  });
  if(!cur.length)cats.textContent="No spending this month yet.";
  var l=$("list");l.innerHTML="";
  cur.slice().sort(function(p,q){return q.d.localeCompare(p.d)}).forEach(function(x){
    var r=document.createElement("div");r.className="item";
    var left=document.createElement("div");
    left.textContent=x.c+(x.n?" - "+x.n:"");
    var s=document.createElement("div");s.className="sub";s.textContent=x.d;left.appendChild(s);
    var right=document.createElement("div");
    var amt=document.createElement("span");amt.textContent=inr(x.a)+" ";
    var del=document.createElement("button");del.type="button";del.className="x";del.textContent="x";
    del.onclick=function(){items=items.filter(function(y){return y!==x});save();render()};
    right.appendChild(amt);right.appendChild(del);
    r.appendChild(left);r.appendChild(right);l.appendChild(r);
  });
}
$("add").onclick=function(){
  var a=Number($("a").value);
  if(!a||a<=0||!$("d").value)return;
  items.push({d:$("d").value,c:$("c").value,a:a,n:$("n").value.trim()});
  $("a").value="";$("n").value="";
  save();render();
};
$("m").onchange=render;
$("bud").oninput=function(){save();render()};
render();
</script>
</body></html>
```
